function domain_contracts_tables():array {$out=[];foreach(domain_contracts_schema(config()['db']['prefix']) as $name=>$sql)$out[$name]=one('SELECT TABLE_NAME FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name=?',[config()['db']['prefix'].$name])!==null;return $out;}
function domain_contracts_audit(int $actor,string $kind,string $detail):void {query('INSERT INTO '.table('audit').' (user_id,action,detail,created_at) VALUES (?,?,?,?)',[$actor,'domain_contracts.'.$kind,$detail,gmdate('Y-m-d H:i:s')]);}
function domain_contracts_ready():bool {
    foreach(['audit','settings','provider_refreshes','provider_refresh_results'] as $name){$engine=one('SELECT ENGINE FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name=?',[config()['db']['prefix'].$name]);if(strtolower($engine['ENGINE']??'')!=='innodb')throw new RuntimeException('Prepare transactional provider inventory first.');}
