    $count=one('SELECT value FROM '.table('settings').' WHERE name=?',['domain_contracts_intent_count'])['value']??null;$results=one('SELECT value FROM '.table('settings').' WHERE name=?',['domain_contracts_result_count'])['value']??null;
    $shared=(int)query('SELECT COUNT(*) FROM '.table('provider_refreshes').' WHERE BINARY operation=?',['domain.contract'])->fetchColumn();$audits=(int)query('SELECT COUNT(*) FROM '.table('audit').' WHERE BINARY action IN (?,?,?)',['domain_contracts.prepared','domain_contracts.bound','domain_contracts.observed'])->fetchColumn();
    if($version===''){if($count!==null||$results!==null||$shared>0||$audits>0)throw new RuntimeException('Renewal date history needs recovery from the original database.');foreach($tables as $n=>$exists)if($exists&&(int)query('SELECT COUNT(*) FROM '.table($n))->fetchColumn()>0)throw new RuntimeException('Unmarked renewal date history needs recovery.');return false;}
    if($version!=='1'||in_array(false,$tables,true)||!is_string($count)||!preg_match('/\A(?:0|[1-9][0-9]{0,18})\z/',$count)||!is_string($results)||!preg_match('/\A(?:0|[1-9][0-9]{0,18})\z/',$results))throw new RuntimeException('Renewal date storage needs recovery.');
    foreach(array_keys($tables) as $n){$e=one('SELECT ENGINE FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name=?',[config()['db']['prefix'].$n]);if(strtolower($e['ENGINE']??'')!=='innodb')throw new RuntimeException('Renewal date storage must be transactional.');}
    $bindings=(int)query('SELECT COUNT(*) FROM '.table('domain_contract_bindings'))->fetchColumn();$dates=(int)query('SELECT COUNT(*) FROM '.table('domain_contract_dates'))->fetchColumn();
    if((string)$bindings!==$count||$shared!==$bindings||(int)query('SELECT COUNT(*) FROM '.table('audit').' WHERE BINARY action=?',['domain_contracts.bound'])->fetchColumn()!==$bindings||(int)query('SELECT COUNT(*) FROM '.table('audit').' WHERE BINARY action=?',['domain_contracts.prepared'])->fetchColumn()!==1||(int)query('SELECT COUNT(*) FROM '.table('audit').' WHERE BINARY action=?',['domain_contracts.observed'])->fetchColumn()!==$dates)throw new RuntimeException('Renewal date sequence needs recovery.');
    if(one('SELECT b.id FROM '.table('domain_contract_bindings').' b LEFT JOIN '.table('provider_refreshes').' f ON f.id=b.id WHERE f.id IS NULL OR BINARY f.operation<>? LIMIT 1',['domain.contract'])||one('SELECT d.id FROM '.table('domain_contract_dates').' d LEFT JOIN '.table('domain_contract_bindings').' b ON b.id=d.id WHERE b.id IS NULL LIMIT 1'))throw new RuntimeException('Renewal date binding history needs recovery.');
    $resultCount=(string)query('SELECT COUNT(*) FROM '.table('provider_refresh_results').' r JOIN '.table('provider_refreshes').' f ON f.id=r.id WHERE BINARY f.operation=?',['domain.contract'])->fetchColumn();$complete=(int)query('SELECT COUNT(*) FROM '.table('provider_refresh_results').' r JOIN '.table('provider_refreshes').' f ON f.id=r.id WHERE BINARY f.operation=? AND BINARY r.state=?',['domain.contract','complete'])->fetchColumn();
    if($resultCount!==$results||$complete!==$dates)throw new RuntimeException('Renewal date result history needs recovery.');
    // Fixed-query cross-family witnesses catch loss before selecting a surviving older subject.
    if(one('SELECT b.id FROM '.table('domain_contract_bindings').' b JOIN '.table('provider_refreshes').' f ON f.id=b.id LEFT JOIN '.table('audit')." a ON a.user_id=b.actor_id AND BINARY a.action='provider.refresh_started' AND BINARY a.detail=BINARY CONCAT('Refresh ',f.id,' profile ',f.profile_id,' revision ',f.profile_revision) WHERE a.id IS NULL LIMIT 1")||one('SELECT b.id FROM '.table('domain_contract_bindings').' b LEFT JOIN '.table('audit')." a ON a.user_id=b.actor_id AND BINARY a.action='domain_contracts.bound' AND BINARY a.detail=BINARY CONCAT('Read ',b.id,' binding ',b.binding_sha256) WHERE a.id IS NULL LIMIT 1"))throw new RuntimeException('Renewal date intent audit needs recovery.');
    if(one('SELECT b.id FROM '.table('domain_contract_bindings').' b JOIN '.table('provider_refresh_results').' r ON r.id=b.id LEFT JOIN '.table('audit')." a ON a.user_id=b.actor_id AND BINARY a.action='provider.refresh_finished' AND BINARY a.detail=BINARY CONCAT('Refresh ',b.id,' ',r.state,IF(r.reason='','',' '),r.reason) WHERE a.id IS NULL LIMIT 1"))throw new RuntimeException('Renewal date outcome audit needs recovery.');
    return true;
}
function domain_contracts_validate_schema(string $name,string $sql):void {
    catalog_validate_schema($name,$sql,[]);$indexes=[];
    foreach(all('SHOW FULL COLUMNS FROM '.table($name)) as $c){$ascii=in_array($c['Field'],['id','link_id','binding_sha256','renewal_date','document_sha256'],true);if($c['Default']!==null||$c['Extra']!==''||$c['Collation']!==($ascii?'ascii_bin':($c['Field']==='binding_json'?'utf8mb4_unicode_ci':null)))throw new RuntimeException('Incompatible renewal date columns.');}
    foreach(all('SHOW INDEX FROM '.table($name)) as $i){if($i['Sub_part']!==null||$i['Index_type']!=='BTREE')throw new RuntimeException('Incompatible renewal date indexes.');$indexes[$i['Key_name']][0]=(int)$i['Non_unique'];$indexes[$i['Key_name']][1][(int)$i['Seq_in_index']]=$i['Column_name'];}foreach($indexes as &$i){ksort($i[1]);$i[1]=array_values($i[1]);}unset($i);ksort($indexes);$expected=['PRIMARY'=>[0,['id']]];if($name==='domain_contract_bindings')$expected['link_reads']=[1,['link_id']];if($indexes!==$expected)throw new RuntimeException('Incompatible renewal date indexes.');
    $f=all('SELECT k.COLUMN_NAME,k.REFERENCED_TABLE_NAME,k.REFERENCED_COLUMN_NAME,r.DELETE_RULE,r.UPDATE_RULE FROM information_schema.KEY_COLUMN_USAGE k JOIN information_schema.REFERENTIAL_CONSTRAINTS r ON r.CONSTRAINT_SCHEMA=k.CONSTRAINT_SCHEMA AND r.CONSTRAINT_NAME=k.CONSTRAINT_NAME AND r.TABLE_NAME=k.TABLE_NAME WHERE k.TABLE_SCHEMA=DATABASE() AND k.TABLE_NAME=? AND k.REFERENCED_TABLE_NAME IS NOT NULL',[config()['db']['prefix'].$name]);$target=$name==='domain_contract_bindings'?'provider_refreshes':'domain_contract_bindings';
    if(count($f)!==1||$f[0]['COLUMN_NAME']!=='id'||$f[0]['REFERENCED_TABLE_NAME']!==config()['db']['prefix'].$target||$f[0]['REFERENCED_COLUMN_NAME']!=='id'||!in_array($f[0]['DELETE_RULE'],['RESTRICT','NO ACTION'],true)||!in_array($f[0]['UPDATE_RULE'],['RESTRICT','NO ACTION'],true))throw new RuntimeException('Incompatible renewal date relationships.');
}
function domain_contracts_prepare(#[SensitiveParameter] string $password):void {
    if(db()->inTransaction())throw new LogicException('Renewal date preparation cannot run inside a transaction.');
    staff_locked(function()use($password):void{$actor=provider_settings_owner($password);if(!provider_registrar_ready())throw new RuntimeException('Prepare registered domains first.');$ready=domain_contracts_ready();$tables=domain_contracts_tables();foreach(domain_contracts_schema(config()['db']['prefix']) as $n=>$sql)if($tables[$n])domain_contracts_validate_schema($n,$sql);foreach(domain_contracts_schema(config()['db']['prefix']) as $n=>$sql){if(!$tables[$n])db()->exec($sql);domain_contracts_validate_schema($n,$sql);}if(!$ready)staff_transaction(function()use($actor):void{save_setting('domain_contracts_schema_version','1');save_setting('domain_contracts_intent_count','0');save_setting('domain_contracts_result_count','0');domain_contracts_audit((int)$actor['id'],'prepared','Renewal date observations ready');});});
}
